<?php require_once __DIR__.'/../includes/permissions.php';require_login();if($_SERVER['REQUEST_METHOD']==='GET'){require_permission('residents.view');$s=db()->prepare('SELECT id,patient_id,first_name,middle_name,last_name,birth_date,sex,barangay,status FROM residents WHERE status="Active" AND (patient_id LIKE ? OR first_name LIKE ? OR last_name LIKE ?) ORDER BY last_name,first_name LIMIT 200');$q='%'.trim((string)get('q','')).'%';$s->execute([$q,$q,$q]);json_response(['success'=>true,'data'=>$s->fetchAll()]);}if($_SERVER['REQUEST_METHOD']==='POST'){require_permission('residents.create');$d=json_decode(file_get_contents('php://input'),true)?:$_POST;$required=['first_name','last_name','birth_date','sex','barangay'];foreach($required as $k)if(empty($d[$k]))json_response(['success'=>false,'message'=>"Missing $k"],422);$pdo=db();$pdo->beginTransaction();$s=$pdo->prepare('INSERT INTO residents(patient_id,first_name,middle_name,last_name,birth_date,sex,barangay,contact_number,address,created_by) VALUES("PENDING",?,?,?,?,?,?,?,?,?)');$s->execute([$d['first_name'],$d['middle_name']??null,$d['last_name'],$d['birth_date'],$d['sex'],$d['barangay'],$d['contact_number']??null,$d['address']??null,current_user()['id']]);$id=(int)$pdo->lastInsertId();$pid='SR-'.date('Y').'-'.str_pad((string)$id,6,'0',STR_PAD_LEFT);$pdo->prepare('UPDATE residents SET patient_id=? WHERE id=?')->execute([$pid,$id]);$pdo->commit();audit('CREATE','residents',$id,'Resident created via API');json_response(['success'=>true,'patient_id'=>$pid,'id'=>$id],201);}
